function spawnBlob(
  world: World,
  kind: 'blue' | 'red',
  x: number,
  y: number,
  energy: number,
  generation: number,
  parentId: number | null,
  speedTrait: number,
  visionTrait: number,
): Blob {
  const b: Blob = {
    id: world.nextId++,
    kind,
    x,
    y,
    vx: 0,
    vy: 0,
    energy,
    bornAt: world.tick,
    generation,
    parentId,
    state: 'wander',
    stateTimer: 0,
    targetId: null,
    heading: world.rng() * Math.PI * 2,
    wanderTimer: Math.floor(world.rng() * 80),
    speedTrait,
    visionTrait,
    lastAteAt: world.tick,
  }
  return b
}

function mutateTrait(rng: Rng, parent: number): number {
  return clamp(parent * (1 + (rng() - 0.5) * 0.14), 0.6, 1.5)
}

