          prey.state = 'flee'
          prey.targetId = b.id
          prey.graceUntil = Math.max(prey.graceUntil, world.tick + 40)
          b.state = 'digest'
          b.stateTimer = Math.max(8, Math.floor(p.redPauseTime * 0.35))
          world.events.push({ type: 'miss', x: prey.x, y: prey.y, redId: b.id, blueId: prey.id })
        }
